        address asserter = address(c.optimisticAsserter());

        vm.recordLogs();
        vm.prank(asserter);
        c.requestPrice(identifier, time, ancillaryData);

        Vm.Log[] memory logs = vm.getRecordedLogs();
        // Count PriceRequestAdded logs emitted by c matching the exact fuzzed params.
        uint256 matches;
        for (uint256 i = 0; i < logs.length; i++) {
            if (
                logs[i].emitter == address(c) &&
                logs[i].topics.length == 3 &&
                logs[i].topics[0] == keccak256("PriceRequestAdded(bytes32,uint256,bytes)") &&
                logs[i].topics[1] == identifier &&
                logs[i].topics[2] == bytes32(time) &&
                abi.decode(logs[i].data, (bytes)) keccak256 equal check
            ) {
                matches++;
            }
        }

        // General rule: every requestPrice call from the asserter emits exactly one
        // PriceRequestAdded event carrying the exact (identifier, time, ancillaryData).
        // The mutant emits none, so matches == 0 for every input.
        assertTrue(matches == 1, "requestPrice must emit exactly one PriceRequestAdded event");
    }
}

