pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address stub;

    function setUp() public {
        __InvMutHandleStub h = new __InvMutHandleStub();
        stub = address(h);
        c = new C(address(new __InvMutHandleStub()));
    }

    function testFuzz_property(bytes32 identifier, uint256 time, uint256 len, bytes32 seed) public {
        // keep the ancillary-data length in a wide admissible band (non-empty so the
        // event payload is non-trivial, bounded to stay within gas limits)
        len = bound(len, 1, 4096);
        time = bound(time, 0, block.timestamp + 1e18);

        bytes memory ancillary = new bytes(len);
        for (uint256 i = 0; i < len; ++i) {
            ancillary[i] = bytes1(uint8(uint256(seed) >> ((i % 31) * 8)));
        }

        // successful path: called by the optimistic asserter (the stub address)
        vm.startPrank(stub);
        uint256 g0 = gasleft();
        c.requestPrice(identifier, time, ancillary);
        uint256 successGas = g0 - gasleft();
        vm.stopPrank();

        // revert path: same calldata, unauthorized caller -> modifier reverts before any log
        address outsider = address(uint160(uint256(seed) ^ uint256(identifier) ^ time));
        vm.assume(outsider != stub);
        vm.startPrank(outsider);
        bool ok = true;
        uint256 g1 = gasleft();
        try c.requestPrice(identifier, time, ancillary) {
            ok = true;
        } catch {
            ok = false;
        }
        uint256 revertGas = g1 - gasleft();
        vm.stopPrank();

        // general rule: the successful (event-emitting) call must consume strictly more
        // gas than the reverting call, for every admissible input.
        assertTrue(ok == false && successGas > revertGas);
    }
}

