pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(new __InvMutHandleStub())); }

    function testFuzz_property(bytes32 identifier, uint256 time, bytes memory ancillaryData) public {
        vm.recordLogs();
        vm.prank(address(new __InvMutHandleStub()));
        // caller must be the optimisticAsserter: deploy stub and use its address
        // (optimisticAsserter is the stub contract deployed in setUp)
        vm.stopPrank();
        vm.prank(address(c.optimisticAsserter()));
        c.requestPrice(identifier, bound(time, 1, type(uint256).max), ancillaryData);

        Vm.Log[] memory logs = vm.getRecordedLogs();
        bool found = false;
        uint256 emittedTime = 0;
        bytes32 topic = keccak256("PriceRequestAdded(bytes32,uint256,bytes)");
        for (uint256 i = 0; i < logs.length; i++) {
            if (logs[i].topics[0] == topic) {
                (bytes32 id, uint256 t, bytes memory ad) = abi.decode(logs[i].data, (bytes32, uint256, bytes));
                if (id == identifier && keccak256(ad) == keccak256(ancillaryData)) {
                    found = true;
                    emittedTime = t;
                }
            }
        }
        assertTrue(found && emittedTime == time, "emitted time must equal the requested time");
    }
}

